states.label:
OBC_Down
en:
OBC_Front_OffDone = false;
OBC_Rear_OffDone = false;

Init
en:
Ready = false;
VCU_PowerOnReq = 0;
VCU_UrgencyCutOffPowerReq = 0;
VCU_DCDC1_En = 2;
EDrv1_PowOnCmd = 0;
EDrv2_PowOnCmd = 0;
DcdcCmd = 0;
VCU_ShrRlyCtl = 0;
VCU_HghVtgCtl = 0;
OnOffCmd = 0;
OBCEnSig = 0;
Flag = 1;

PowerOff
en:
Front_OffDone = false;
Rear_OffDone = false;

OBC_Relay_PosPreEn
en:
EDrv1_PowOnCmd = 1;
EDrv2_PowOnCmd = 1;
VCU_ShrRlyCtl = 1;
VCU_HghVtgCtl = 1;
OBC_Ready = OBC_HVCReady && OBC_PDUReady;

Relay_NegEn
en:
Ready = false;
VCU_PowerOnReq = 1;
Flag = 3;

Relay_PosPreEn
du:
    EDrv1_PowOnCmd = 1;
    EDrv2_PowOnCmd = 1;
    VCU_ShrRlyCtl = 1;
    VCU_HghVtgCtl = 1;
    Ready = HVCReady && PDUReady;

OBC_Front_LVDown
en:Cnt3 = 0;
du:
    VCU_DCDC1_En = 2;     % 停止，不能写0
    Cnt3 = Cnt3+1;

OBC_Rear_LVDown
en:Cnt4 = 0;
du:
    DcdcCmd = 0;
    Cnt4 = Cnt4+1;

Front_LVDown
en:Cnt1 = 0;
du:
    VCU_DCDC1_En = 2;     % 停止，不能写0
    VCU2OilMotor_En = 0;
    VCU2DrvMotor_En = 0;
    Cnt1 = Cnt1+1;

Rear_LVDown
en:Cnt2 = 0;
du:
    DcdcCmd = 170;
    TM_MCU_Enable = 0;
    ISG_MCU_Enable = 0;
    Cnt2 = Cnt2+1;

HVC_Ready
en:
    HVCReady = true;
    VCU_DCDC1_En = 1;
    VCU2OilMotor_En = 1;
    VCU2DrvMotor_En = 1;

PDU_Ready
en:
    PDUReady = true;
    DcdcCmd = 1;
    TM_MCU_Enable = 1;
    ISG_MCU_Enable = 1;
